<script setup lang="ts">
import { ref, watch } from 'vue';
import { watchToast } from './toast';
const props = defineProps<{ token:string }>();
type Category = {id:number; merchant_id:number; name:string; sort_order:number; status:string};
type Sku = {id:number; product_id:number; name:string; price:string; status:string};
const tab=ref<'category'|'sku'>('category'), merchant=ref(''), product=ref(''), categories=ref<Category[]>([]), skus=ref<Sku[]>([]), error=ref(''), message=ref(''), busy=ref(false);
watchToast(error, 'error'); watchToast(message, 'success');
const editCategory=ref<number|null>(null), editSku=ref<number|null>(null), showForm=ref(false);
const category=ref({name:'',sort_order:0,status:'active'}), sku=ref({name:'',price:'',status:'active'});
const stocks=ref<Record<number,number>>({});
watch(merchant,()=>{categories.value=[];resetCategory();});
watch(product,()=>{skus.value=[];stocks.value={};resetSku();});
async function api(path:string,method='GET',body?:unknown){const r=await fetch('/api/v1'+path,{method,headers:{Authorization:`Bearer ${props.token}`,...(body===undefined?{}:{'Content-Type':'application/json'})},body:body===undefined?undefined:JSON.stringify(body)});if(!r.ok){const d=await r.json().catch(()=>({}));throw new Error(typeof d.detail==='string'?d.detail:'操作失败，请检查输入');}return r.status===204?null:r.json();}
async function action(fn:()=>Promise<void>){error.value='';message.value='';busy.value=true;try{await fn();}catch(e){error.value=e instanceof Error?e.message:'操作失败';}finally{busy.value=false;}}
function validId(value:string){if(!/^[1-9]\d*$/.test(value))throw new Error('请输入有效的编号');return Number(value);}
async function loadCategories(){const id=validId(merchant.value);categories.value=await api(`/categories?merchant_id=${id}&limit=100`);}
async function loadSkus(){const id=validId(product.value);const data:Sku[]=await api(`/products/${id}/skus`);const inventory=await Promise.all(data.map(s=>api(`/skus/${s.id}/inventory`)));skus.value=data;stocks.value=Object.fromEntries(data.map((s,i)=>[s.id,inventory[i].available]));}
function resetCategory(){editCategory.value=null;category.value={name:'',sort_order:0,status:'active'};}
function resetSku(){editSku.value=null;sku.value={name:'',price:'',status:'active'};}
async function saveCategory(){await action(async()=>{const id=validId(merchant.value);const body={...category.value,sort_order:Number(category.value.sort_order)};await api(editCategory.value?`/categories/${editCategory.value}`:'/categories',editCategory.value?'PATCH':'POST',editCategory.value?body:{...body,merchant_id:id});resetCategory();await loadCategories();showForm.value=false;message.value='保存成功';});}
async function saveSku(){await action(async()=>{const id=validId(product.value);const body={...sku.value};await api(editSku.value?`/skus/${editSku.value}`:`/products/${id}/skus`,editSku.value?'PATCH':'POST',body);resetSku();await loadSkus();showForm.value=false;message.value='保存成功';});}
async function remove(path:string, name:string, reload:()=>Promise<void>){if(!confirm(`确定删除“${name}”吗？`))return;await action(async()=>{await api(path,'DELETE');await reload();message.value='删除成功';});}
async function saveStock(id:number){await action(async()=>{const available=Number(stocks.value[id]);if(!Number.isInteger(available)||available<0)throw new Error('库存必须是非负整数');await api(`/skus/${id}/inventory`,'PUT',{available});message.value='库存已更新';});}
</script>
<template>
<main class="catalog">
  <div class="filter-panel"><div class="filter-fields"><label>管理类型<select v-model="tab" @change="error='';message='';showForm=false"><option value="category">商品分类</option><option value="sku">规格与库存</option></select></label><label v-if="tab==='category'">商户编号<input v-model.trim="merchant" type="number" min="1" placeholder="请输入商户编号" @keyup.enter="action(loadCategories)"></label><label v-else>商品编号<input v-model.trim="product" type="number" min="1" placeholder="请输入商品编号" @keyup.enter="action(loadSkus)"></label></div><div class="filter-actions"><button class="secondary" @click="tab==='category' ? merchant='' : product=''; error='';message=''">重置</button><button class="primary" :disabled="busy" @click="action(tab==='category' ? loadCategories : loadSkus)">搜索</button></div></div>
  <section class="data-panel"><div class="toolbar"><h2>{{tab==='category'?'商品分类':'规格与库存'}}</h2><div class="toolbar-actions"><button class="primary" @click="tab==='category' ? resetCategory() : resetSku();error='';showForm=true">＋ 新增{{tab==='category'?'分类':'规格'}}</button><button class="refresh" aria-label="刷新" title="刷新" :disabled="busy" @click="action(tab==='category' ? loadCategories : loadSkus)">↻</button></div></div>

    <div class="table"><table v-if="tab==='category'"><thead><tr><th>编号</th><th>名称</th><th>排序</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in categories" :key="item.id"><td>{{item.id}}</td><td>{{item.name}}</td><td>{{item.sort_order}}</td><td><span class="status" :class="item.status">{{item.status==='active'?'启用':'停用'}}</span></td><td><button class="link" @click="editCategory=item.id;category={name:item.name,sort_order:item.sort_order,status:item.status};error='';showForm=true">编辑</button><button class="link danger" @click="remove(`/categories/${item.id}`,item.name,loadCategories)">删除</button></td></tr><tr v-if="!categories.length"><td colspan="5" class="empty">输入商户编号查询分类</td></tr></tbody></table>
    <table v-else><thead><tr><th>编号</th><th>规格</th><th>价格</th><th>状态</th><th>可售库存</th><th>操作</th></tr></thead><tbody><tr v-for="item in skus" :key="item.id"><td>{{item.id}}</td><td>{{item.name}}</td><td>¥ {{Number(item.price).toFixed(2)}}</td><td><span class="status" :class="item.status">{{item.status==='active'?'启用':'停用'}}</span></td><td><input v-model.number="stocks[item.id]" class="stock" type="number" min="0" step="1" :aria-label="`${item.name}可售库存`"><button class="link" :disabled="busy" @click="saveStock(item.id)">保存库存</button></td><td><button class="link" @click="editSku=item.id;sku={name:item.name,price:item.price,status:item.status};error='';showForm=true">编辑</button><button class="link danger" @click="remove(`/skus/${item.id}`,item.name,loadSkus)">删除</button></td></tr><tr v-if="!skus.length"><td colspan="6" class="empty">输入商品编号查询规格</td></tr></tbody></table></div><div class="footer">{{tab==='category'?`当前显示 ${categories.length} 条分类（最多 100 条）`:`当前显示 ${skus.length} 条规格`}}</div>
  </section>
  <div v-if="showForm" class="overlay" @click.self="showForm=false"><div class="dialog" role="dialog" aria-modal="true" :aria-label="tab==='category'?'分类信息':'规格信息'"><div class="dialog-head"><h2>{{tab==='category'?(editCategory?'编辑分类':'新增分类'):(editSku?'编辑规格':'新增规格')}}</h2><button class="close" type="button" aria-label="关闭" @click="showForm=false">×</button></div><form v-if="tab==='category'" @submit.prevent="saveCategory"><label>分类名称<input v-model.trim="category.name" maxlength="120" required></label><label>排序<input v-model.number="category.sort_order" type="number" required></label><label>状态<select v-model="category.status"><option value="active">启用</option><option value="inactive">停用</option></select></label><div class="dialog-actions"><button type="button" class="secondary" @click="showForm=false">取消</button><button class="primary" :disabled="busy">保存</button></div></form><form v-else @submit.prevent="saveSku"><label>规格名称<input v-model.trim="sku.name" maxlength="120" required></label><label>价格（元）<input v-model="sku.price" type="number" min="0" step="0.01" required></label><label>状态<select v-model="sku.status"><option value="active">启用</option><option value="inactive">停用</option></select></label><div class="dialog-actions"><button type="button" class="secondary" @click="showForm=false">取消</button><button class="primary" :disabled="busy">保存</button></div></form></div></div>
</main></template>
<style scoped>
.catalog{flex:1;min-height:0;display:flex;flex-direction:column;gap:14px;background:#f0f2f5;padding:20px;color:#172233}.filter-panel{min-height:80px;padding:20px;background:#fff;border-radius:6px;display:flex;align-items:center;justify-content:space-between;gap:20px}.filter-fields,.filter-actions,.toolbar,.toolbar-actions,.dialog-head,.dialog-actions{display:flex;align-items:center;gap:10px}.filter-fields{gap:24px;flex-wrap:wrap}.filter-fields label{display:flex;align-items:center;gap:12px;font-size:14px;white-space:nowrap}.filter-fields input,.filter-fields select{width:200px}.data-panel{flex:1;min-height:400px;background:#fff;border-radius:6px;padding:10px;display:flex;flex-direction:column}.toolbar{justify-content:space-between;min-height:50px;padding-bottom:10px}.toolbar h2,.dialog h2{font-size:18px;margin:0;color:#111c2d}.table{flex:1;overflow:auto;border:1px solid #dce4ef;border-radius:4px}.table table{width:100%;min-width:600px;border-collapse:collapse;text-align:center;font-size:14px}.table th,.table td{height:50px;padding:10px 14px;border-bottom:1px solid #dce4ef}.table th{background:#eef3f9;color:#3d4a5b;font-weight:600}.empty{color:#8c99a9;height:100px!important}.status{padding:4px 8px;border-radius:4px;background:#effcf3;color:#52c878}.status.inactive{background:#f1f3f5;color:#788594}.footer{padding:15px 5px;color:#718096;font-size:12px}.catalog input,.catalog select{box-sizing:border-box;height:40px;padding:0 12px;border:1px solid #dce3ed;border-radius:5px;background:#fff;color:#25364b;font:inherit}.catalog input::placeholder{color:#b8c2cf}.stock{width:90px}.catalog button{border-radius:5px;padding:9px 15px;font-size:13px;cursor:pointer}.primary{background:#5267ff;border:1px solid #5267ff;color:white}.secondary{background:#fff;border:1px solid #dce3ed;color:#334155}.refresh{width:38px;height:38px;padding:0!important;border:1px solid #dce3ed;border-radius:50%!important;background:#fff;color:#607087;font-size:22px!important}.link{border:0;background:none;color:#5267ff;padding:6px!important}.danger,.error{color:#ba3e3e}.success{color:#32845a}.catalog button:disabled{opacity:.5;cursor:not-allowed}.overlay{position:fixed;inset:0;z-index:10;display:grid;place-items:center;padding:20px;background:#14253c66}.dialog{width:min(480px,100%);background:#fff;border-radius:9px;padding:24px;box-shadow:0 20px 60px #15253a30}.dialog-head{justify-content:space-between;margin-bottom:23px}.close{border:0;background:none;color:#8090a0;font-size:24px!important}.dialog label{display:block;margin:16px 0;color:#42546a;font-size:13px}.dialog label input,.dialog label select{display:block;width:100%;margin-top:8px}.dialog-actions{justify-content:flex-end;margin-top:24px}.catalog button:focus-visible,.catalog input:focus-visible,.catalog select:focus-visible{outline:2px solid #5267ff;outline-offset:2px}@media(max-width:700px){.catalog{padding:12px}.filter-panel{padding:14px;flex-wrap:wrap}.filter-fields{width:100%}.filter-fields label{width:100%}.filter-fields input,.filter-fields select{flex:1;min-width:0}.filter-actions{margin-left:auto}.data-panel{min-height:380px}.toolbar{flex-wrap:wrap}}

/* 与其余管理页共用 40px 控件高度。 */
.filter-panel input,.filter-panel select,.dialog input,.dialog select{height:40px}.catalog .primary,.catalog .secondary{box-sizing:border-box;min-width:72px;height:40px;padding:0 16px;display:inline-flex;align-items:center;justify-content:center;font-size:14px;line-height:1;white-space:nowrap}.catalog .refresh{box-sizing:border-box;width:40px;height:40px;display:inline-flex;align-items:center;justify-content:center;line-height:1}.toolbar-actions,.filter-actions{align-items:center}.stock{height:40px}


.catalog{padding:8px;gap:8px}.filter-panel,.data-panel{border:2px solid #d8e0ec}.filter-panel{padding:14px 16px}.data-panel{padding:8px}.table{border:2px solid #cfdae8}.table th,.table td{border-bottom:1px solid #cfd9e6}@media(max-width:700px){.catalog{padding:6px;gap:6px}.filter-panel{padding:12px}.data-panel{padding:6px}}


.catalog{padding:2px;gap:2px}.filter-panel{min-height:68px;padding:10px 12px;border-radius:0}.data-panel{padding:4px;border-radius:0}.toolbar{min-height:52px;padding-bottom:4px}.footer{padding:8px 4px}@media(max-width:700px){.catalog{padding:2px;gap:2px}.filter-panel{padding:10px}.data-panel{padding:4px}}
</style>